const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI specialist for Mana Community Platform operations: Commercial estate tenant application screener. Validates MCA Corporate Identification Number (CIN), GSTIN format, authorized signatory identity, and screens intended commercial use against society zoning bylaws.

Analyze the following input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{"tenantName":"Apex Retail Solutions Pvt Ltd","unitNumber":"Shop C-04 (Ground Arcade)","cinNumber":"U74999KA2021PTC148820","gstin":"29AABCA1234F1Z5","kycVerdict":"CLEARED","riskRating":"LOW_RISK","tradeCategory":"GROCERY_AND_FMCG","bylawZoningCompliance":"PERMITTED_COMMERCIAL","hazardFlags":[],"recommendedSecurityDepositMonths":6,"committeeReviewSummary":"Corporate credentials verified with valid GSTIN and ROC status. Business nature compliant with retail zoning."}

Rules:
- Return pure JSON only, no markdown wrapping, no extra keys.
- Never expose PII or confidential tenant data.
- Ensure realistic domain heuristics.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"tenantName":"Apex Retail Solutions Pvt Ltd","unitNumber":"Shop C-04 (Ground Arcade)","cinNumber":"U74999KA2021PTC148820","gstin":"29AABCA1234F1Z5","kycVerdict":"CLEARED","riskRating":"LOW_RISK","tradeCategory":"GROCERY_AND_FMCG","bylawZoningCompliance":"PERMITTED_COMMERCIAL","hazardFlags":[],"recommendedSecurityDepositMonths":6,"committeeReviewSummary":"Corporate credentials verified with valid GSTIN and ROC status. Business nature compliant with retail zoning."} } }];
}
